1	import { useState, useEffect, useCallback, useId } from "react";
2	import { useNavigate, useSearchParams } from "react-router-dom";
3	import {
4	  ScanLine,
5	  Info,
6	  AlertCircle,
7	  Loader2,
8	  Globe,
9	  Lock,
10	} from "lucide-react";
11	import { Card, CardContent } from "@/components/ui/card";
12	import { Button } from "@/components/ui/button";
13	import { Input } from "@/components/ui/input";
14	import { Progress } from "@/components/ui/progress";
15	import {
16	  Select,
17	  SelectContent,
18	  SelectItem,
19	  SelectTrigger,
20	  SelectValue,
21	} from "@/components/ui/select";
22	import { ScanProgressTimeline } from "@/components/shared/ScanProgressTimeline";
23	import { BrowserFrame } from "@/components/shared/BrowserFrame";
24	import { PageTransition } from "@/components/shared/PageTransition";
25	import { CRO_PILLARS, SCAN_STEPS, PAGE_TYPES } from "@/lib/constants";
26	import { useAuth } from "@/contexts/AuthContext";
27	import { useCreateScan } from "@/hooks/use-scans";
28	import { useScan } from "@/hooks/use-scans";
29	import { toast } from "sonner";
30	import type { PageType } from "@/types";
31	import { cn } from "@/lib/utils";
32	
33	/** Basic URL validation — checks structure, not reachability */
34	function isValidUrl(str: string): boolean {
35	  try {
36	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
37	    return url.protocol === "https:" || url.protocol === "http:";
38	  } catch {
39	    return false;
40	  }
41	}
42	
43	/** Normalize URL: prepend https:// if missing */
44	function normalizeUrl(str: string): string {
45	  const trimmed = str.trim();
46	  if (!trimmed) return trimmed;
47	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
48	  return `https://${trimmed}`;
49	}
50	
51	// ── Map scan status to step index ───────────────────────────────
52	
53	function statusToStep(status: string): number {
54	  switch (status) {
55	    case "pending": return 0;
56	    case "analyzing": return 3;
57	    case "completed": return SCAN_STEPS.length;
58	    case "failed": return -1;
59	    default: return 0;
60	  }
61	}
62	
63	const Scan = () => {
64	  const navigate = useNavigate();
65	  const [searchParams] = useSearchParams();
66	  const [rawUrl, setRawUrl] = useState(searchParams.get("url") || "");
67	  const [pageType, setPageType] = useState<PageType>(
68	    (searchParams.get("type") as PageType) || "landing"
69	  );
70	  const [urlError, setUrlError] = useState<string | null>(null);
71	
72	  // activeScanId drives the polling query
73	  const [activeScanId, setActiveScanId] = useState<string | null>(null);
74	  const [simulatedStep, setSimulatedStep] = useState(-1);
75	  const [scanFailed, setScanFailed] = useState(false);
76	
77	  const inputId = useId();
78	  const { user, profile } = useAuth();
79	  const isAuthenticated = !!user;
80	  const createScan = useCreateScan();
81	
82	  const scansUsed = profile?.scans_used ?? 0;
83	  const scanLimit = profile?.scan_limit ?? 3;
84	  const scansRemaining = scanLimit - scansUsed;
85	  const atLimit = scansRemaining <= 0;
86	
87	  // Poll the scan row while it's pending/analyzing
88	  const { data: pollingScan } = useScan(activeScanId ?? undefined, {
89	    refetchInterval: activeScanId ? 2000 : false,
90	  });
91	
92	  const isAnalyzing = activeScanId !== null;
93	  const normalizedUrl = normalizeUrl(rawUrl);
94	
95	  const totalSteps = SCAN_STEPS.length;
96	  const currentStep = isAnalyzing
97	    ? pollingScan
98	      ? statusToStep(pollingScan.status)
99	      : simulatedStep
100	    : -1;
101	  const progressPercent = currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);
102	
103	  // When polling finds a completed/failed scan, navigate or show error
104	  useEffect(() => {
105	    if (!pollingScan) return;
106	    if (pollingScan.status === "completed") {
107	      setTimeout(() => navigate(`/reports/${pollingScan.id}`), 600);
108	    } else if (pollingScan.status === "failed") {
109	      setActiveScanId(null);
110	      setSimulatedStep(-1);
111	      setScanFailed(true);
112	    }
113	    // eslint-disable-next-line react-hooks/exhaustive-deps
114	  }, [pollingScan?.status]);
115	
116	  // Simulate step progression while waiting for the edge function
117	  useEffect(() => {
118	    if (!isAnalyzing || !activeScanId) return;
119	    if (pollingScan?.status === "completed" || pollingScan?.status === "failed") return;
120	    if (simulatedStep >= totalSteps - 1) return;
121	
122	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
123	    const timer = setTimeout(
124	      () => setSimulatedStep((prev) => prev + 1),
125	      durations[simulatedStep] ?? 1200
126	    );
127	    return () => clearTimeout(timer);
128	    // totalSteps is derived from a constant — safe to omit
129	    // eslint-disable-next-line react-hooks/exhaustive-deps
130	  }, [isAnalyzing, activeScanId, simulatedStep, pollingScan?.status]);
131	
132	  const startAnalysis = useCallback(() => {
133	    setUrlError(null);
134	    if (!rawUrl.trim()) {
135	      setUrlError("Please enter a URL.");
136	      return;
137	    }
138	    if (!isValidUrl(normalizedUrl)) {
139	      setUrlError("Enter a valid URL like https://example.com/page");
140	      return;
141	    }
142	
143	    // Unauthenticated users: gate the scan and redirect to signup
144	    if (!isAuthenticated) {
145	      toast.info("Create a free account to start scanning", {
146	        description: "Sign up in seconds — no credit card required.",
147	        action: {
148	          label: "Sign up free",
149	          onClick: () =>
150	            navigate(
151	              `/signup?redirect=/scan&url=${encodeURIComponent(normalizedUrl)}`
152	            ),
153	        },
154	      });
155	      navigate(`/signup?redirect=/scan&url=${encodeURIComponent(normalizedUrl)}`);
156	      return;
157	    }
158	
159	    if (atLimit) return;
160	
161	    setSimulatedStep(0);
162	
163	    createScan.mutate(
164	      { url: normalizedUrl, page_type: pageType },
165	      {
166	        onSuccess: (scan) => {
167	          setActiveScanId(scan.id);
168	        },
169	        onError: (err: unknown) => {
170	          setSimulatedStep(-1);
171	          const message = err instanceof Error ? err.message : "Failed to start scan";
172	          toast.error(message);
173	        },
174	      }
175	    );
176	  }, [rawUrl, normalizedUrl, pageType, isAuthenticated, atLimit, createScan, navigate]);
177	
178	  const handleSubmit = (e: React.FormEvent) => {
179	    e.preventDefault();
180	    startAnalysis();
181	  };
182	
183	  // ── Analysis Progress View ──────────────────────────────────
184	  if (isAnalyzing) {
185	    let hostname = rawUrl;
186	    try { hostname = new URL(normalizedUrl).hostname; } catch { /* keep raw */ }
187	
188	    const displayStep = Math.max(0, currentStep);
189	
190	    return (
191	      <PageTransition>
192	        <div className="mx-auto max-w-2xl space-y-6">
193	          <div>
194	            <h2 className="text-xl font-semibold tracking-tight text-foreground">Analyzing your page</h2>
195	            <p className="mt-1 text-sm text-muted-foreground">
196	              Scanning <span className="font-medium text-foreground">{hostname}</span> — this usually takes 20-40 seconds
197	            </p>
198	          </div>
199	
200	          {/* Progress bar */}
201	          <div className="space-y-1.5">
202	            <div className="flex items-center justify-between text-sm">
203	              <span className="text-muted-foreground">
204	                Step {Math.min(displayStep + 1, totalSteps)} of {totalSteps}
205	              </span>
206	              <span className="tabular-nums font-medium text-foreground">{Math.min(progressPercent, 100)}%</span>
207	            </div>
208	            <Progress value={Math.min(progressPercent, 100)} className="h-2" />
209	          </div>
210	
211	          {/* Browser frame */}
212	          <BrowserFrame url={normalizedUrl}>
213	            <div className="relative flex h-52 items-center justify-center bg-gradient-to-br from-slate-50 via-white to-slate-50">
214	              {/* Scanning animation */}
215	              <div className="absolute inset-x-0 top-0 h-1 overflow-hidden">
216	                <div className="h-full w-1/3 animate-[shimmer_1.5s_ease-in-out_infinite] bg-gradient-to-r from-transparent via-primary/30 to-transparent" />
217	              </div>
218	              <div className="text-center">
219	                <Loader2 className="mx-auto mb-3 h-8 w-8 animate-spin text-primary" />
220	                <p className="text-sm font-medium text-muted-foreground">
221	                  {displayStep < totalSteps ? SCAN_STEPS[displayStep]?.label : "Finalizing report"}...
222	                </p>
223	              </div>
224	            </div>
225	          </BrowserFrame>
226	
227	          {/* Timeline */}
228	          <Card className="border-border/50 shadow-soft">
229	            <CardContent className="p-6">
230	              <ScanProgressTimeline steps={SCAN_STEPS} currentStep={displayStep} />
231	            </CardContent>
232	          </Card>
233	        </div>
234	      </PageTransition>
235	    );
236	  }
237	
238	  // ── URL Input Form ──────────────────────────────────────────
239	  return (
240	    <PageTransition>
241	      <div className="mx-auto max-w-2xl space-y-8">
242	        <div className="text-center">
243	          <h2 className="text-xl font-semibold tracking-tight text-foreground">Analyze your page</h2>
244	          <p className="mt-2 text-muted-foreground">
245	            Enter any URL to get a detailed CRO audit with actionable recommendations
246	          </p>
247	        </div>
248	
249	        {/* URL Input Card */}
250	        <Card className="border-border/50 shadow-soft">
251	          <CardContent className="p-8">
252	            <form onSubmit={handleSubmit} className="space-y-4">
253	              <div>
254	                <label htmlFor={inputId} className="mb-1.5 block text-sm font-medium text-foreground">
255	                  Page URL
256	                </label>
257	                <div className="relative">
258	                  <Globe className="absolute left-4 top-1/2 h-4.5 w-4.5 -translate-y-1/2 text-muted-foreground" />
259	                  <Input
260	                    id={inputId}
261	                    type="text"
262	                    placeholder="example.com/landing-page"
263	                    value={rawUrl}
264	                    onChange={(e) => { setRawUrl(e.target.value); setUrlError(null); }}
265	                    className={cn(
266	                      "h-14 rounded-xl border-border/50 bg-card pl-11 pr-5 text-base placeholder:text-muted-foreground focus-visible:border-primary focus-visible:ring-primary/20",
267	                      urlError && "border-red-300 focus-visible:border-red-400 focus-visible:ring-red-400/20"
268	                    )}
269	                  />
270	                </div>
271	                {urlError && (
272	                  <p className="mt-1.5 flex items-center gap-1 text-sm text-red-600">
273	                    <AlertCircle className="h-3.5 w-3.5" />
274	                    {urlError}
275	                  </p>
276	                )}
277	              </div>
278	
279	              <div>
280	                <label className="mb-1.5 block text-sm font-medium text-foreground">Page type</label>
281	                <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
282	                  <SelectTrigger className="h-12 rounded-xl border-border/50 bg-card">
283	                    <SelectValue placeholder="Select page type" />
284	                  </SelectTrigger>
285	                  <SelectContent>
286	                    {PAGE_TYPES.map((type) => (
287	                      <SelectItem key={type.value} value={type.value}>
288	                        {type.label}
289	                      </SelectItem>
290	                    ))}
291	                  </SelectContent>
292	                </Select>
293	                <p className="mt-1 text-xs text-muted-foreground">
294	                  Page type affects how we weight each CRO pillar in the overall score
295	                </p>
296	              </div>
297	
298	              <Button
299	                type="submit"
300	                className="h-14 w-full rounded-xl text-base font-semibold"
301	                disabled={!rawUrl.trim() || (isAuthenticated && (atLimit || createScan.isPending))}
302	              >
303	                {isAuthenticated && atLimit ? (
304	                  "Scan limit reached — Upgrade to continue"
305	                ) : isAuthenticated && createScan.isPending ? (
306	                  <>
307	                    <Loader2 className="mr-2 h-5 w-5 animate-spin" />
308	                    Starting scan...
309	                  </>
310	                ) : !isAuthenticated ? (
311	                  <>
312	                    <Lock className="mr-2 h-5 w-5" />
313	                    Sign Up to Start Analysis
314	                  </>
315	                ) : (
316	                  <>
317	                    <ScanLine className="mr-2 h-5 w-5" />
318	                    Start Analysis
319	                  </>
320	                )}
321	              </Button>
322	            </form>
323	
324	            {/* Usage indicator — only shown to authenticated users */}
325	            {isAuthenticated ? (
326	              <div className="mt-4 flex items-center justify-center gap-4 text-xs text-muted-foreground">
327	                <span className="flex items-center gap-1">
328	                  {atLimit ? (
329	                    <AlertCircle className="h-3.5 w-3.5 text-red-500" />
330	                  ) : scansRemaining === 1 ? (
331	                    <AlertCircle className="h-3.5 w-3.5 text-amber-500" />
332	                  ) : (
333	                    <Info className="h-3.5 w-3.5" />
334	                  )}
335	                  {scansUsed}/{scanLimit} scans used this month
336	                </span>
337	                <span>&middot;</span>
338	                <span>~30 seconds per scan</span>
339	              </div>
340	            ) : (
341	              <div className="mt-4 rounded-lg border border-blue-100 bg-blue-50/60 px-4 py-3 text-center">
342	                <p className="text-xs text-blue-700">
343	                  Free account — 3 scans/month, no credit card required.{" "}
344	                  <a href="/signup" className="font-medium underline underline-offset-2 hover:text-blue-900">
345	                    Create account
346	                  </a>
347	                </p>
348	              </div>
349	            )}
350	          </CardContent>
351	        </Card>
352	
353	        {/* Scan failure retry card */}
354	        {scanFailed && (
355	          <Card className="border-destructive/30 bg-destructive/5">
356	            <CardContent className="flex items-center gap-4 p-6">
357	              <AlertCircle className="h-8 w-8 text-destructive shrink-0" />
358	              <div>
359	                <p className="font-medium text-foreground">Analysis failed</p>
360	                <p className="text-sm text-muted-foreground mt-0.5">
361	                  The scan engine encountered an error. Your scan count was not affected.
362	                </p>
363	              </div>
364	              <Button
365	                onClick={() => { setScanFailed(false); startAnalysis(); }}
366	                className="ml-auto shrink-0"
367	              >
368	                Try Again
369	              </Button>
370	            </CardContent>
371	          </Card>
372	        )}
373	
374	        {/* What we analyze */}
375	        <div>
376	          <h3 className="mb-4 text-center text-xs font-semibold uppercase tracking-widest text-muted-foreground">
377	            7 pillars we analyze
378	          </h3>
379	          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
380	            {CRO_PILLARS.map((pillar) => {
381	              const Icon = pillar.icon;
382	              return (
383	                <Card
384	                  key={pillar.key}
385	                  className="group border-border/50 shadow-soft hover:shadow-soft-md transition-all"
386	                >
387	                  <CardContent className="flex flex-col items-center p-4 text-center">
388	                    <div className="mb-2.5 flex h-9 w-9 items-center justify-center rounded-lg bg-primary/8 group-hover:bg-primary/15 transition-colors">
389	                      <Icon className="h-4 w-4 text-primary" />
390	                    </div>
391	                    <p className="text-xs font-medium text-foreground leading-tight">
392	                      {pillar.label}
393	                    </p>
394	                    <p className="mt-1 text-[10px] leading-snug text-muted-foreground">
395	                      {Math.round(pillar.weight * 100)}% weight
396	                    </p>
397	                  </CardContent>
398	                </Card>
399	              );
400	            })}
401	          </div>
402	        </div>
403	
404	        {/* How scoring works */}
405	        <Card className="border-border/40 bg-muted/30 shadow-none">
406	          <CardContent className="p-5">
407	            <div className="flex items-start gap-3">
408	              <Info className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
409	              <div className="text-xs text-muted-foreground leading-relaxed">
410	                <span className="font-medium text-foreground">How scoring works:</span> Each pillar is scored 0-100 based on specific checks.
411	                Pillar weights vary by page type — for example, CTA Effectiveness is weighted 22% on landing pages but only 12% on blog posts.
412	                Your overall score is a weighted average compared against industry benchmarks.
413	              </div>
414	            </div>
415	          </CardContent>
416	        </Card>
417	      </div>
418	    </PageTransition>
419	  );
420	};
421	
422	export default Scan;
