74	
75	export default function AuditLog() {
76	  const [page, setPage] = useState(0);
77	  const [actionFilter, setActionFilter] = useState("");
78	
79	  const { data, isLoading, isError } = useAuditLog({
80	    page,
81	    pageSize: PAGE_SIZE,
82	    actionFilter: actionFilter || undefined,
83	  });
84	
85	  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;
86	
87	  return (
88	    <div className="space-y-6">
89	      <PageHeader
90	        title="Audit Log"
91	        description="Chronological record of all admin actions."
92	      />
93	
94	      {/* Filter */}
95	      <div className="flex items-center gap-3">
96	        <Filter className="h-4 w-4 text-muted-foreground" />
97	        <Select
98	          value={actionFilter}
99	          onValueChange={(v) => {
100	            setActionFilter(v);
101	            setPage(0);
102	          }}
103	        >
104	          <SelectTrigger className="w-[180px]" aria-label="Filter by action type">
105	            <SelectValue />
106	          </SelectTrigger>
107	          <SelectContent>
108	            {ACTION_OPTIONS.map((opt) => (
109	              <SelectItem key={opt.value} value={opt.value}>
110	                {opt.label}
111	              </SelectItem>
112	            ))}
113	          </SelectContent>
114	        </Select>
115	        {actionFilter && (
116	          <Button
117	            variant="ghost"
118	            size="sm"
119	            onClick={() => {
120	              setActionFilter("");
121	              setPage(0);
122	            }}
123	          >
124	            Clear filter
125	          </Button>
126	        )}
127	        {data && (
128	          <span className="ml-auto text-sm text-muted-foreground">
129	            {data.total.toLocaleString()} entries
130	          </span>
131	        )}
132	      </div>
133	
134	      {/* Entries */}
135	      {isLoading ? (
136	        <LogSkeleton />
137	      ) : isError ? (
138	        <div
139	          role="alert"
140	          className="flex items-center gap-3 rounded-xl border border-destructive/20 bg-destructive/5 p-4"
141	        >
142	          <Filter className="h-5 w-5 text-destructive shrink-0" />
143	          <p className="text-sm font-medium text-destructive">
144	            Failed to load audit log. Check your admin permissions or refresh the page.
145	          </p>
146	        </div>
147	      ) : data?.entries.length === 0 ? (
148	        <EmptyState
149	          icon={ScrollText}
150	          title="No audit log entries"
151	          description={
152	            actionFilter
153	              ? "No entries match the selected action filter."
154	              : "Admin actions will appear here once they occur."
155	          }
156	        />
157	      ) : (
158	        <ol className="space-y-2.5" aria-label="Audit log entries">
159	          {data?.entries.map((entry) => {
160	            const metadata = entry.metadata as Record<string, string>;
161	            const metaKeys = Object.keys(metadata).filter(
162	              (k) => metadata[k] !== undefined && metadata[k] !== null
163	            );
164	
165	            return (
166	              <li key={entry.id}>
167	                <Card className="border-border/50 shadow-soft hover:border-slate-300 transition-colors">
168	                  <CardContent className="flex items-start gap-4 p-4">
169	                    {/* Icon */}
170	                    <div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-muted/50">
171	                      <ScrollText className="h-4 w-4 text-slate-500" />
172	                    </div>
173	
174	                    {/* Content */}
175	                    <div className="flex-1 min-w-0">
